import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
} from '@angular/core';
import { PresentsetupService } from '../../services/presentsetup/presentsetup.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { ActivatedRoute } from '@angular/router';
import { presentSetupData, TypeRes } from '../../interfaces/presentsetup';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { LocationStrategy } from '@angular/common';
import { HeaderService } from '../../../core/services/header/header.service';
import { UserPermissionService } from '../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-subtype',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [IconComponent],
  templateUrl: './subtype.component.html',
  styleUrl: './subtype.component.scss',
})
export class SubtypeComponent {
  nCaseid: string;
  subTypes: TypeRes[] = [];
  presentSession: presentSetupData = {} as presentSetupData;
  constructor(
    private readonly PSservice: PresentsetupService,
    private cm: CommonfunctionService,
    private route: ActivatedRoute,
    private cdr: ChangeDetectorRef,
    private location: LocationStrategy,
    private hs: HeaderService,
    private userPermissions: UserPermissionService

  ) {
    var params = this.route.snapshot.params;
    params = JSON.parse(decodeURIComponent(params['id']));
    this.nCaseid = params && params['id'] ? params['id'] : '';
    hs.nCaseid = this.nCaseid;

    history.pushState(null, null, window.location.href);
    // check if back or forward button is pressed.
    this.location.onPopState(() => {
      history.pushState(null, null, window.location.href);
    });

    userPermissions.userPermissionList(this.nCaseid);

  }

  async ngOnInit() {
    if (!this.nCaseid) {
      this.cm.gotoUrl('/user/dashboard');
    }
    this.presentSession = await this.PSservice.getRvalue(this.nCaseid);
    this.subTypes = await this.PSservice.getSTypes(this.nCaseid);

    // if (this.subTypes?.length > 0) {
    //   this.subTypes.sort((a, b) => a.nValue - b.nValue).reverse();
    // }
    this.cdr.detectChanges();
  }

  async setup(item) {
    this.PSservice.setRvalue({
      nCaseid: this.presentSession.nCaseid,
      nSTypeid: item.nValue,
      cSType: item?.jOther?.type,
    });
    if (item?.jOther?.type == 'F' || (item?.jOther?.type == 'W' && !item?.bIsHaveSchedules) || (item?.jOther?.type == 'C' && !item?.nPresentid)) {
      this.cm.gotoUrl('/present/setup', { id: this.nCaseid, type: item?.jOther?.type });


      // if (item?.jOther?.type == 'F') {
      //   this.cm.gotoUrl('/present/setup', { id: this.nCaseid });
    } else if (item?.jOther?.type == 'W') {
      this.cm.gotoUrl(
        `${item?.bIsHaveSchedules
          ? '/present/schedule-list'
          : '/present/createWitness'
        }`,
        { id: this.nCaseid }
      );
    } else if (item?.jOther?.type == 'C') {
      if (item.nPresentid) {
        this.cm.gotoUrl('/present/core-case', {
          id: this.nCaseid,
          nPid: item.nPresentid,
        });
      } else {
        this.cm.gotoUrl('/present/core-case', { id: this.nCaseid });
      }
    }
  }
}
